import{_ as e,c as a,o as r,a3 as s}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"Manufacturing","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/manufacturing/index.md","filePath":"master/supply-chain/manufacturing/index.md","lastUpdated":1791902625000}'),o={name:"master/supply-chain/manufacturing/index.md"};function n(i,t,d,h,u,l){return r(),a("div",null,t[0]||(t[0]=[s(`<h1 id="manufacturing" tabindex="-1">Manufacturing <a class="header-anchor" href="#manufacturing" aria-label="Permalink to &quot;Manufacturing&quot;">​</a></h1><p>Manufacturing turns components into finished products. You describe the recipe once, then create a manufacturing order (MO) each time you want to build some units. Aureus reserves the components, schedules the work and records what you produce.</p><blockquote><p><strong>In simple words:</strong> Write the recipe, order a build, do the work, get finished goods in stock.</p></blockquote><p>Open the app from the top bar: <code>Manufacturing</code>. It has four menus: <strong>Operations</strong>, <strong>Products</strong>, <strong>Configurations</strong> and <strong>Settings</strong>.</p><h2 id="the-whole-flow" tabindex="-1">The whole flow <a class="header-anchor" href="#the-whole-flow" aria-label="Permalink to &quot;The whole flow&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Product + Bill of Materials  →  Warehouse steps  →  Manufacturing order (Draft)</span></span>
<span class="line"><span>        →  Confirm  →  Plan  →  Work orders  →  Produce All  →  Done</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Stage</th><th>What happens</th><th>Page</th></tr></thead><tbody><tr><td>Set up</td><td>A goods product and a recipe (Bill of Materials)</td><td><a href="./basic-setup/configure-product.html">Configure a product</a>, <a href="./basic-setup/bill-of-materials.html">Bill of materials</a></td></tr><tr><td>Choose warehouse steps</td><td>One, two or three steps for stock movement</td><td><a href="./basic-setup/one-step-manufacturing.html">One step</a>, <a href="./basic-setup/two-step-manufacturing.html">Two steps</a>, <a href="./basic-setup/three-step-manufacturing.html">Three steps</a></td></tr><tr><td>Order</td><td>Create the MO in <strong>Draft</strong></td><td><a href="./workflows/manufacturing-orders.html">Manufacturing orders</a></td></tr><tr><td>Confirm</td><td>Components are reserved, state <strong>Confirmed</strong></td><td><a href="./workflows/manufacturing-orders.html">Manufacturing orders</a></td></tr><tr><td>Plan</td><td>Work orders get dates on work centers</td><td><a href="./workflows/plan-and-schedule.html">Plan and schedule</a></td></tr><tr><td>Work</td><td>Operators start, pause and finish each step</td><td><a href="./workflows/work-orders.html">Work orders</a></td></tr><tr><td>Produce</td><td>Components are used, finished goods arrive, state <strong>Done</strong></td><td><a href="./workflows/produce-and-consume.html">Produce and consume</a></td></tr></tbody></table><h2 id="settings-that-open-menus" tabindex="-1">Settings that open menus <a class="header-anchor" href="#settings-that-open-menus" aria-label="Permalink to &quot;Settings that open menus&quot;">​</a></h2><p>Some menus stay hidden until you switch a setting on. Go to <code>Manufacturing → Settings → Manage Operations</code>.</p><table tabindex="0"><thead><tr><th>Setting</th><th>What it turns on</th></tr></thead><tbody><tr><td><strong>Work Orders</strong></td><td>The <strong>Work Orders</strong> menu, <strong>Work Centers</strong>, <strong>Operations</strong>, the <strong>Work Orders</strong> tab on an MO and the <strong>Operations</strong> tab on a BoM</td></tr><tr><td><strong>Work Order Dependencies</strong></td><td>Steps that wait for other steps</td></tr><tr><td>Multi Steps Routes (Inventory)</td><td>The warehouse <strong>Manufacturing</strong> steps (two and three steps)</td></tr></tbody></table><p>See <a href="./get-started/manufacturing-settings.html">Manufacturing settings</a>.</p><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li><strong>Get started</strong>: <a href="./get-started/">Overview</a>, <a href="./get-started/manufacturing-settings.html">Manufacturing settings</a>, <a href="./get-started/first-steps.html">First steps</a></li><li><strong>Basic setup</strong>: <a href="./basic-setup/">Overview</a>, <a href="./basic-setup/configure-product.html">Configure a product</a>, <a href="./basic-setup/bill-of-materials.html">Bill of materials</a>, <a href="./basic-setup/one-step-manufacturing.html">One step</a>, <a href="./basic-setup/two-step-manufacturing.html">Two steps</a>, <a href="./basic-setup/three-step-manufacturing.html">Three steps</a>, <a href="./basic-setup/manufacturing-order-costs.html">Manufacturing order costs</a></li><li><strong>Advanced configuration</strong>: <a href="./advanced-configuration/">Overview</a>, <a href="./advanced-configuration/work-centers.html">Work centers</a>, <a href="./advanced-configuration/operations.html">Operations</a>, <a href="./advanced-configuration/work-order-dependencies.html">Work order dependencies</a>, <a href="./advanced-configuration/bom-variants.html">BoM variants</a></li><li><strong>Workflows</strong>: <a href="./workflows/">Overview</a>, <a href="./workflows/manufacturing-orders.html">Manufacturing orders</a>, <a href="./workflows/plan-and-schedule.html">Plan and schedule</a>, <a href="./workflows/work-orders.html">Work orders</a>, <a href="./workflows/produce-and-consume.html">Produce and consume</a>, <a href="./workflows/lots-and-serial-numbers.html">Lots and serial numbers</a></li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../inventories/">Inventory overview</a></li><li><a href="./../purchase/">Purchase overview</a></li><li><a href="./../inventories/warehouses/warehouses.html">Warehouses</a></li></ul>`,15)]))}const p=e(o,[["render",n]]);export{f as __pageData,p as default};
